      ['Hayranlık', 'Bir şeyin güzelliği ya da üstünlüğü karşısında etkilenme\nİpucu: "ne güzel", "eşsiz", "büyülenmek"', 'Dağların ardından doğan güneşe uzun uzun baktım.'],
      ['Pişmanlık', 'Yapılan ya da yapılmayan bir şey için üzülme\nİpucu: "keşke", "-seydim", "neden", "boşa"', 'Keşke o gün dedeme bir telefon açsaydım.'],
      ['Umut (iyimserlik)', 'Gelecekten iyi şeyler bekleme\nİpucu: "yarın", "bahar", "filiz", "güneş doğacak"', 'Bu kışın ardından mutlaka bahar gelecek.'],
      ['Umutsuzluk (karamsarlık)', 'Gelecekten beklentinin kalmaması\nİpucu: "boşuna", "hiçbir şey değişmeyecek", "karanlık"', 'Ne yapsam boş, bu yol hiç bitmeyecek.'],
      ['Çaresizlik', 'Bir durum karşısında elinden bir şey gelmemesi\nİpucu: "elimden ne gelir", "çare yok"', 'Kapı kilitli, ses veren yok; bekledim sadece.'],
      ['Yalnızlık', 'Kimsesiz, yapayalnız hissetme\nİpucu: "tek başıma", "kimse", "boş oda"', 'Kalabalık şehirde bir tek ben yabancıyım.'],
      ['Kaygı (endişe, tedirginlik)', 'Olabilecek kötü bir şeyden korkma\nİpucu: "ya ... olursa", "içim içime sığmadı"', 'Ya sınavda her şeyi unutursam?'],
      ['Korku', 'Tehlike karşısında duyulan ürperti\nİpucu: "titremek", "kalbim duracaktı"', 'Karanlık koridorda adım sesleri yaklaştı.'],
      ['Öfke (kızgınlık)', 'Bir haksızlık ya da hata karşısında sert tepki\nİpucu: ünlem, sert sözcükler, "yeter"', 'Yeter artık, bu kadarına katlanamam!'],
      ['Sitem', 'Sevilen birine kırılgınlığı yumuşak bir dille söylemek\nİpucu: "sen de mi", "bekledim ama"', 'Bir mektubuna bile değmedim demek.'],
      ['Yakınma (şikayet)', 'Bir durumdan hoşnut olmadığını dile getirme\nİpucu: "bu ne hâl", "hep aynı"', 'Her sabah aynı trafik, aynı gürültü.'],
      ['Alay (ironi)', 'Bir şeyi tersini söyleyerek küçümseme\nİpucu: Tırnak içi, "ne de akıllı", ters anlam', 'Ne çalışkan öğrenci, sınavdan önceki gece kitabı açmış!'],
      ['Övgü / takdir', 'Birinin iyi yönünü öne çıkarma\nİpucu: "emeği", "alkışı hak ediyor"', 'Öğretmenimizin sabrı hepimize örnek oldu.'],
      ['Eleştiri', 'Bir şeyin eksik ya da yanlış yönünü gösterme\nİpucu: "ne yazık ki", "oysa", "ama"', 'Park yapıldı ama tek bir ağaç dikilmedi.'],
      ['Minnet (şükran)', 'Bir iyilik karşısında borçluluk ve teşekkür hissi\nİpucu: "sayesinde", "hakkını ödeyemem"', 'Bugünkü hâlimi babamın emeğine borçluyum.'],
      ['Gurur (övünç)', 'Kendisiyle ya da bir yakınıyla övünme\nİpucu: "başım dik", "göğsüm kabardı"', 'Karnemi uzatırken annemin gözleri parlıyordu.'],
      ['Merak', 'Bir şeyi öğrenme isteği\nİpucu: Soru, "acaba", "nasıl"', 'Acaba yıldızların ötesinde neler var?'],
      ['Şaşkınlık (hayret)', 'Beklenmedik bir durum karşısında kalıp kalmak\nİpucu: "inanamadım", "donup kaldım"', 'Kapıyı açınca tüm sınıfı karşımda buldum.'],
      ['Hayal kırıklığı', 'Beklenen şeyin gerçekleşmemesi\nİpucu: "oysa", "sanmıştım", "beklemiştim"', 'Geleceğini sanmıştım, ama sandalyesi boş kaldı.'],
      ['Kararlılık (azim)', 'Bir hedeften vazgeçmemek\nİpucu: "mutlaka", "asla vazgeçmeyeceğim"', 'Düşsem de kalkacağım, bu yolu bitireceğim.'],
      ['Bıkkınlık (usanç)', 'Tekrar eden bir durumdan bıkmak\nİpucu: "yine", "hep", "artık"', 'Yine aynı masa, yine aynı sorular.'],
      ['Huzur (dinginlik)', 'İç rahatlığı, sakinlik\nİpucu: "sessizce", "serin", "dingin"', 'Deniz kıyısında sadece dalgaları dinledim.'],
      ['Merhamet (acıma)', 'Zor durumdaki bir canlıya duyulan şefkat\nİpucu: "zavallı", "üşümüş"', 'Soğukta titreyen kediye montumu örttüm.'],
      ['Vatan / doğa sevgisi', 'Yurda ya da doğaya bağlılık\nİpucu: "bayrak", "toprağım", "yurdum"', 'Bu toprağın her taşında bir hatıra var.'],
    ]),
    StudyTopicDef('lgs_tr.7', 'Karıştırılan duygular ve ipuçları', [
      ['Özlem – Pişmanlık', 'Özlemde kavuşma isteği vardır; pişmanlıkta kişi kendi yaptığına üzülür.', '"Seni çok özledim" (özlem) / "Seni kırmasaydım" (pişmanlık)'],
      ['Sitem – Öfke', 'Sitemde sevgi ve kırılganlık vardır, dil yumuşaktır; öfkede dil serttir.', '"Bir kez olsun arasaydın" (sitem) / "Bir daha yüzüme bakma!" (öfke)'],
      ['Sitem – Yakınma', 'Sitem bir kişiye yönelir; yakınma bir durumdan, hayattan, şartlardan şikayettir.', '"Beni unuttun" (sitem) / "Bu şehirde nefes alınmıyor" (yakınma)'],
      ['Hüzün – Umutsuzluk', 'Hüzünde üzüntü vardır ama gelecek kapanmamıştır; umutsuzlukta gelecekten beklenti kalmaz.', '"Gözlerim doldu" (hüzün) / "Hiçbir şey düzelmeyecek" (umutsuzluk)'],
      ['Hayranlık – Övgü', 'Hayranlık içte duyulan etkilenmedir; övgü bu beğeniyi dışa vurup birini yüeltmektir.', '"Manzaraya büyülenerek baktım" / "Bu eser ustalığını gösteriyor"'],
      ['Eleştiri – Alay', 'Eleştiri doğrudan söylenir; alayda söylenen, kastedilenin tersidir.', '"Ders çalışmadın" (eleştiri) / "Ne de çok çalışmışsın!" (alay)'],
      ['Kaygı – Korku', 'Kaygı olası bir geleceğe yönelir; korku o an yaşanan tehlikeye tepkidir.', '"Ya geç kalırsam?" / "Köpek üzerime koşuyordu"'],
      ['Umut – Kararlılık', 'Umut beklentidir; kararlılık eyleme geçme isteğidir.', '"Güzel günler gelecek" / "O günleri ben getireceğim"'],
      ['Hayal kırıklığı – Şaşkınlık', 'Hayal kırıklığı olumsuzdur; şaşkınlık olumlu da olumsuz da olabilir.', '"Onu böyle sanmazdım" / "Gözlerime inanamadım"'],
      ['Duygu bulmanın beş adımı', '1. Metni sonuna kadar okuyun; duygu çoğu zaman son dizelerde netleşir.\n2. Olumlu ve olumsuz sözcükleri sayın; hangisi ağır basıyor?\n3. "Keşke", "yine", "acaba", "ya ... olursa" gibi anahtar kalıpları işaretleyin.\n4. Noktalamaya bakın: ünlem coşku ya da öfkeye, üç nokta hüzne, soru merak ya da sitemi işaret edebilir.\n5. Kalan iki duygu için: kime yöneliyor, geçmişe mi geleceğe mi bakıyor?', 'Dikkat: "ağır basan duygu" soruluyorsa metinde geçen her duygu doğru cevap değildir; bütüne yayılmış asıl duyguyu seçin.'],
      ['Duygu sorularında üç kural', '"Keşke" pişmanlık ya da özlem, "yine/hep" bıkkınlık, "acaba" merak, "ya ... olursa" kaygı işaretidir.\nSitem kişiye, yakınma duruma yönelir.\nÖvgü gibi görünen ama tersini kastettiği belli olan cümle alaydır.', ''],
    ]),
    StudyTopicDef('lgs_tr.8', 'Söz sanatları (LGS)', [
      ['Benzetme (teşbih)', 'Aralarında ortak bir yön bulunan iki varlıktan zayıf olanın güçlü olana benzetilmesi.\nİpucu: gibi, kadar, sanki, adeta, -ce/-ca, -sı. Edat ya da yön olmasa da benzetme olur.', 'Ninemin yüzü bir harita gibi kırışık.\nSen bir güneşsin bu evde.'],
      ['Benzetmenin dört öğesi', 'Benzeyen (zayıf olan), kendisine benzetilen (güçlü olan), benzetme yönü (ortak özellik), benzetme edatı (bağlayıcı sözcük).', '"Kar gibi beyaz elleri vardı": benzeyen eller, kendisine benzetilen kar, yön beyazlık, edat gibi.'],
      ['Her "gibi" benzetme değildir', '"Saat beş gibi gel": yaklaşıklık. "Yorgun gibi görünüyorsun": tahmin. "Senin gibi ben de düşünüyorum": aynı türden iki varlık kıyaslanır, zayıf-güçlü ilişkisi yoktur, benzetme yok.', ''],
      ['Kişileştirme (teşhis)', 'İnsan dışındaki varlıklara (hayvan, bitki, eşya, doğa olayları, soyut kavramlar) insana özgü özellik ya da davranış verilmesi.\nİpucu: ağlamak, gülmek, üzülmek, beklemek, özlemek, sarılmak, fısıldamak.', 'Rüzgar kapıya vurup beni çağırdı.\nDağlar üzüldü giden köylülere.\nDikkat: "Güneş doğdu", "Nehir aktı" kişileştirme değildir.'],
      ['Konuşturma (intak)', 'İnsan dışındaki varlıkların konuşturulması. Konuşturma olan yerde kişileştirme de vardır.\nİpucu: tırnak içi söz, "dedi", "söyledi", "seslendi".', 'Yaşlı çınar, "Yüz yıldır bu köyü gölgemde büyüttüm." dedi.\nDikkat: "Ey deniz, sakin ol!" konuşturma değildir; varlık söz söylemeli.'],
      ['Abartma (mübalağa)', 'Bir durumu, olayı ya da özelliği olduğundan çok büyük ya da çok küçük göstermek.\nKendine sor: "Bu gerçekten olabilir mi?" Olamıyorsa abartma vardır.', 'O kadar ağladım ki gözyaşlarımla bir göl doldu.\nSesi dağları yerinden oynattı.'],
      ['Karşıtlık (tezat)', 'Anlamca karşıt kavram ya da durumların bir arada kullanılması.\nİpucu: ağlamak/gülmek, gece/gündüz, sıcak/soğuk, var/yok. İki karşıt durum da karşıtlık oluşturur.', 'Dışarıda kar yağıyor, içimde yaz güneşi.\nZenginin sofrası dolu, yoksulun kabı boş.'],
      ['Karıştırılan: Kişileştirme – Konuşturma', 'Varlık söz söylüyorsa konuşturma (ve aynı zamanda kişileştirme) vardır; sadece insan gibi davranıyorsa yalnız kişileştirme vardır.', '"Ay gülümsedi" (kişileştirme) / "Ay, \'Uyu artık\' dedi" (ikisi birden)'],
      ['Karıştırılan: Benzetme – Kişileştirme', 'Benzetmede iki varlık açıkça yan yana konur; kişileştirmede varlık doğrudan insan gibi davranır.', '"Ağaçlar asker gibi sıralandı" (benzetme) / "Ağaçlar nöbet tuttu" (kişileştirme)'],
      ['Karıştırılan: Benzetme – Abartma', 'İkisi bir arada olabilir; benzetmede ortak yön aranır, abartmada "gerçekçi mi?" diye bakılır.', '"Dağ gibi dalgalar gemiyi yuttu" (ikisi birden)'],
      ['Karıştırılan: Karşıtlık – Zıt anlamlı sözcük sorusu', 'Karşıtlık anlatımı güçlendirmek için kurulur; zıt sözcük sorusunda sadece anlam ilişkisi sorulur.', '"Güldüm ama içim ağlıyordu" (hem karşıtlık hem kişileştirme)'],
      ['Karıştırılan: Seslenme – Konuşturma', 'Varlığa seslenmek konuşturma değildir; varlık konuşmalıdır.', '"Ey rüzgar, haber götür!" (konuşturma yok)'],
      ['Çok sanatlı dize çözümü', 'Benzetme: deniz anneye benzetiliyor ("gibi" var).\nKişileştirme: denize "sarılmak" eylemi veriliyor.\nAbartma: "bin yıldır ağlamak" gerçekçi değil.\nKonuşturma ve karşıtlık: yok.', 'Deniz, bin yıldır ağlayan bir anne gibi kıyıya sarılıyor.'],
    ]),
    StudyTopicDef('lgs_tr.9', 'Noktalama işaretleri (ayrıntılı)', [
      ['Nokta ( . ) – 1. kullanım', 'Cümlenin sonuna konur', 'Türk Dil Kurumu, 1932 yılında kurulmuştur.\nSaatler geçtikçe yollara daha mahzun bir ıssızlık çöküyordu. (Reşat Nuri Güntekin)'],
      ['Nokta ( . ) – 2. kullanım', 'Bazı kısaltmaların sonuna konur', 'Alb. (albay), Dr. (doktor), Yrd. Doç. (yardımcı doçent), Prof. (profesör), Cad. (cadde), Sok. (sokak), s. (sayfa), sf. (sıfat), vb. (ve başkası, ve benzeri, ve benzerleri, ve bunun gibi), Alm. (Almanca), Ar. (Arapça), İng. (İngilizce) vb.'],
      ['Nokta ( . ) – 3. kullanım', 'Sayılardan sonra sıra bildirmek için konur', '3. (üçüncü), 15. (on beşinci); II. Mehmet, XIV. Louis, XV. yüzyıl; 2. Cadde, 20. Sokak, 4. Levent vb.'],
      ['Nokta ( . ) – 4. kullanım', 'Arka arkaya sıralandıkları için virgülle veya çizgiyle ayrılan rakamlardan yalnızca sonuncu rakamdan sonra nokta konur', '3, 4 ve 7. maddeler; XII – XIV. yüzyıllar arasında vb.'],
      ['Nokta ( . ) – 5. kullanım', 'Bir yazının maddelerini gösteren rakam veya harflerden sonra konur', 'I.               1.                            A.            a.\nII.              2.                            B.            b.'],
      ['Nokta ( . ) – 6. kullanım', 'Tarihlerin yazılışında gün, ay ve yılı gösteren sayıları birbirinden ayırmak için konur', '29.5.1453, 29.X.1923 vb.'],
      ['Nokta ( . ) – Uyarı 1', 'Tarihlerde ay adları yazıyla da yazılabilir. Bu durumda ay adlarından önce ve sonra nokta kullanılmaz: 29 Mayıs 1453, 29 Ekim 1923 vb.', ''],
      ['Nokta ( . ) – 7. kullanım', 'Saat ve dakika gösteren sayıları birbirinden ayırmak için konur', 'Tren 09.15’te kalktı. Toplantı 13.00’te başladı.\nTören 17.30’da, hükûmet daireleri kapandıktan yarım saat sonra başlayacaktır. (Tarık Buğra)'],
      ['Nokta ( . ) – 8. kullanım', 'Kitap, dergi vb.nin künyelerinin sonuna konur', 'Agâh Sırrı Levend, Türk Dilinde Gelişme ve Sadeleşme Evreleri, TDK Yayınları, Ankara, 1960.'],
      ['Nokta ( . ) – 9. kullanım', 'Dört ve dörtten çok rakamlı sayılar sondan sayılmak üzere üçlü gruplara ayrılarak yazılır ve araya nokta konur', '1.000, 326.197, 49.750.812 vb.'],
      ['Nokta ( . ) – 10. kullanım', 'Genel ağ adreslerinde kullanılır', 'http://tdk.gov.tr'],
      ['Nokta ( . ) – 11. kullanım', 'Matematikte çarpma işareti yerine kullanılır', '4.5=20, 12.6=72 vb.'],
      ['Virgül ( , ) – 1. kullanım', 'Birbiri ardınca sıralanan eş görevli kelime ve kelime gruplarının arasına konur', 'Fırtınadan, soğuktan, karanlıktan ve biraz da korkudan sonra bu sıcak, aydınlık ve sevimli odanın havasında erir gibi oldum. (Halide Edip Adıvar)\nSessiz dereler, solgun ağaçlar, sarı güller\nDillenmiş ağızlarda tutuk dilli gönüller (Faruk Nafiz Çamlıbel)'],
      ['Virgül ( , ) – 2. kullanım', 'Sıralı cümleleri birbirinden ayırmak için konur', 'Umduk, bekledik, düşündük. (Yakup Kadri Karaosmanoğlu)'],
      ['Virgül ( , ) – 3. kullanım', 'Uzun cümlelerde yüklemden uzak düşmüş olan özneyi belirtmek için konur', 'Saniye Hanımefendi, merdivenlerde oğlunun ayak seslerini duyar duymaz, hasretlisini karşılamaya atılan bir genç kadın gibi koltuğundan fırlamış ve ona kapıyı kendi eliyle açmaya gelmişti. (Yakup Kadri Karaosmanoğlu)'],
      ['Virgül ( , ) – 4. kullanım', 'Cümle içinde ara sözleri veya ara cümleleri ayırmak için ara sözlerin veya ara cümlelerin başına ve sonuna konur', 'Zemin bu kadar koyu bir kırmızıya dönüşünce, bir an için de olsa, belirginliğini yitiriverdi sivilceleri. (Elif Şafak)\nŞimdi, efendiler, müsaade buyurursanız, size bir sual sorayım. (Atatürk)'],
      ['Virgül ( , ) – 5. kullanım', 'Anlama güç kazandırmak için tekrarlanan kelimeler arasına konur', 'Akşam, yine akşam, yine akşam,\nGöllerde bu dem bir kamış olsam! (Ahmet Haşim)'],
      ['Virgül ( , ) – 6. kullanım', 'Tırnak içinde olmayan alıntı cümlelerinden sonra konur', 'Adana’ya yarın gideceğim, dedi.\nAç karnına sigara içmekle hiç de iyi etmiyorsun, dedi. (Necati Cumalı)'],
      ['Virgül ( , ) – 7. kullanım', 'Konuşma çizgisinden sonraki alıntı cümlesinin bitimine konur', '– Bu akşam Datça’ya gidiyor musunuz, diye sordu.'],
      ['Virgül ( , ) – 8. kullanım', 'Edebî eserlerde konuşma bölümünden önceki ifadenin sonuna konur', 'Bahçe kapısını açtı. Sermet Bey’e,\n– Bu anahtar köşkü de açar, dedi. (Ömer Seyfettin)'],
      ['Virgül ( , ) – 9. kullanım', 'Kendisinden sonraki cümleye bağlı olarak ret, kabul ve teşvik bildiren hayır, yok, evet, peki, pekâlâ, tamam, olur, hayhay, başüstüne, öyle, haydi, elbette gibi kelimelerden sonra konur', 'Peki, gideriz. Olur, ben de size katılırım. Hayhay, memnun oluruz. Haydi, geç kalıyoruz.\nEvet, kırk seneden beri Türkçe merhale merhale Türkleşiyor. (Yahya Kemal Beyatlı)'],
      ['Virgül ( , ) – 10. kullanım', 'Bir kelimenin kendisinden sonra gelen kelime veya kelime gruplarıyla yapı ve anlam bakımından bağlantısı olmadığını göstermek ve anlam karışıklığını önlemek için kullanılır', 'Bu, tek gözlü, genç fakat ihtiyar görünen bir adamcağızdır. (Halit Ziya Uşaklıgil)\nBu gece, eğlenceleri içlerine sinmedi. (Reşat Nuri Güntekin)'],
      ['Virgül ( , ) – 11. kullanım', 'Hitap için kullanılan kelimelerden sonra konur', 'Efendiler, bilirsiniz ki hayat demek, mücadele, müsademe demektir. (Atatürk)\nSayın Başkan,\nSevgili Kardeşim,'],
      ['Virgül ( , ) – 12. kullanım', 'Sayıların yazılışında kesirleri ayırmak için kullanılır', '38,6 (otuz sekiz tam, onda altı), 0,45 (sıfır tam, yüzde kırk beş)'],
      ['Virgül ( , ) – 13. kullanım', 'Metin içinde art arda gelen zarf-fiil eki almış kelimelerden sonra konur', 'Ancak yemekte bir karara varıp, arkadaşına dikkatli dikkatli bakarak konuştu.'],
      ['Virgül ( , ) – Uyarı 1', 'Metin içinde zarf-fiil eki almış kelimelerden sonra virgül konmaz', 'Cumaları bahçede buluştukça kıza kendisinin adi bir mektep talebesi olmadığını anlatmaya çalışıyordu.     (Halide Edip Adıvar)\nŞimdiye dek, ben kendimi bildim bileli kimse Değirmenoluk köyünden kaçıp da başka köyde çobanlık, yanaşmalık etmedi. (Yaşar Kemal)\nMeydanlığa varmadan bir iki defa İsmail kendisini gördü mü diye kahveye baktı. (Necati Cumalı)'],
      ['Virgül ( , ) – 14. kullanım', 'Özne olarak kullanıldıklarında bu, şu, o zamirlerinden sonra konur', 'Bu, benim gibi yazarlar için hiç kolay olmaz.\nO, eski defterleri çoktan kapatmış, Osmanlıya kucağını açmıştı. (Tarık Buğra)'],
      ['Virgül ( , ) – 15. kullanım', 'Kitap, dergi vb.nin künyelerinde yazar, eser, basımevi vb. maddelerden sonra konur', 'Falih Rıfkı ATAY, Tuna Kıyıları, Remzi Kitabevi, İstanbul, 1938.\nYazarın soyadı önce yazılmışsa soyadından sonra da virgül konur:\nERGİN, Muharrem, Dede Korkut Kitabı, Ankara, 1958.'],
      ['Virgül ( , ) – Uyarı 2', 'Metin içinde ve, veya, yahut, ya … ya bağlaçlarından önce de sonra da virgül konmaz', 'Nihat sabaha kadar uyuyamadı ve şafak sökerken Faik’e bol teşekkürlerle dolu bir kâğıt bırakarak iki gün evvelki cephe dönüşü kıyafeti ile sokağa fırladı. (Peyami Safa)\nYa şevk içinde harap ol ya aşk içinde gönül\nYa lale açmalıdır göğsümüzde yahut gül! (Yahya Kemal Beyatlı)'],
      ['Virgül ( , ) – Uyarı 3', 'Tekrarlı bağlaçlardan önce ve sonra virgül konmaz', 'Hem gider hem ağlar.\nYa bu deveyi gütmeli ya bu diyardan gitmeli. (Atasözü)\nGerek nesirde gerek nazımda yeni bir söyleyişe ulaşılmıştır.'],
      ['Virgül ( , ) – Uyarı 4', 'Cümlede pekiştirme ve bağlama görevinde kullanılan da / de bağlacından sonra virgül konmaz', 'İmlamız lisanımız düzelince, lisanımız da kafamız düzelince düzelecek çünkü o da ancak onlar kadar bozuktur, fazla değil!     (Yahya Kemal Beyatlı)'],
      ['Virgül ( , ) – Uyarı 5', 'Metin içinde -ınca / -ince anlamıyla zarf-fiil görevinde kullanılan mı / mi ekinden sonra virgül konmaz', 'Ben aç yattım mı kötü kötü rüyalar görürüm nedense. (Orhan Kemal)\nÖyle zekiler vardır, konuştular mı ağızlarından bal akıyor sanırsın. (Attila İlhan)'],
      ['Virgül ( , ) – Uyarı 6', 'Şart ekinden sonra virgül konmaz', 'Tenha köşelerde ağız ağıza konuşurken yanlarına biri gelecek olursa hemen susuyorlardı. (Reşat Nuri Güntekin)\nGör gözlerinle de aklın yatarsa anlatıver millete. (Tarık Buğra)'],
      ['Noktalı Virgül ( ; ) – 1. kullanım', 'Cümle içinde virgüllerle ayrılmış tür veya takımları birbirinden ayırmak için konur', 'Erkek çocuklara Doğan, Tuğrul, Aslan, Orhan; kız çocuklara ise İnci, Çiçek, Gönül, Yonca adları verilir.\nTürkiye, İngiltere, Azerbaycan; Ankara, Londra, Bakü.'],
      ['Noktalı Virgül ( ; ) – 2. kullanım', 'Ögeleri arasında virgül bulunan sıralı cümleleri birbirinden ayırmak için konur', 'Sevinçten, heyecandan içim içime sığmıyor; bağırmak, kahkahalar atmak, ağlamak istiyorum.\nAt ölür, meydan kalır; yiğit ölür, şan kalır. (Atasözü)'],
      ['Noktalı Virgül ( ; ) – 3. kullanım', 'İkiden fazla eş değer ögeler arasında virgül bulunan cümlelerde özneden sonra noktalı virgül konabilir', 'Yeni usul şiirimiz; zevksiz, köksüz, acemice görünüyordu. (Yahya Kemal Beyatlı)'],
      ['İki Nokta (: ) – 1. kullanım', 'Kendisiyle ilgili örnek verilecek cümlenin sonuna konur', 'Millî Edebiyat akımının temsilcilerinden bir kısmını sıralayalım: Ömer Seyfettin, Halide Edip Adıvar, Ziya Gökalp, Mehmet Emin Yurdakul, Ali Canip Yöntem.'],
      ['İki Nokta (: ) – 2. kullanım', 'Kendisiyle ilgili açıklama verilecek cümlenin sonuna konur', 'Bu kararın istinat ettiği en kuvvetli muhakeme ve mantık şu idi: Esas, Türk milletinin haysiyetli ve şerefli bir millet olarak yaşamasıdır. (Atatürk)\nKendimi takdim edeyim: Meclis kâtiplerindenim. (Falih Rıfkı Atay)'],
      ['İki Nokta (: ) – 3. kullanım', 'Ses bilgisinde uzun ünlüyü göstermek için kullanılır', 'a:ile, ka:til, usu:le, i:cat.'],
      ['İki Nokta (: ) – 4. kullanım', 'Karşılıklı konuşmalarda, konuşan kişiyi belirten sözlerden sonra konur', 'Bilge Kağan:         Türklerim, işitin!\nÜstten gök çökmedikçe,\nalttan yer delinmedikçe'],
      ['İki Nokta (: ) – 5. kullanım', 'Edebî eserlerde konuşma bölümünden önceki ifadenin sonuna konur', '– Buğdayla arpadan başka ne biter bu topraklarda?\nZiraatçı sayar:\n– Yulaf, pancar, zerzevat, tütün… (Falih Rıfkı Atay)'],
      ['İki Nokta (: ) – 6. kullanım', 'Genel ağ adreslerinde kullanılır', 'http://tdk.gov.tr'],
      ['İki Nokta (: ) – 7. kullanım', 'Matematikte bölme işareti olarak kullanılır', '56:8=7, 100:2=50 vb.'],
      ['Üç Nokta ( … ) – 1. kullanım', 'Anlatım olarak tamamlanmamış cümlelerin sonuna konur', 'Ne çare ki çirkinliği hemencecik ve herkes tarafından görülüveriyordu da bu yanı… (Tarık Buğra)'],
      ['Üç Nokta ( … ) – 2. kullanım', 'Kaba sayıldığı için veya bir başka sebepten dolayı açık yazılmak istenmeyen kelime ve bölümlerin yerine konur', 'Kılavuzu karga olanın burnu b…tan çıkmaz.\nArabacı B…’a yaklaştığını söylüyor, ikide bir fırsat bularak arabanın içine doğru başını çeviriyordu. (Ahmet Hamdi Tanpınar)'],
      ['Üç Nokta ( … ) – 3. kullanım', 'Alıntılarda başta, ortada ve sonda alınmayan kelime veya bölümlerin yerine konur', '… derken şehrin öte başından boğuk boğuk sesler gelmeye başladı… (Tarık Buğra)'],
      ['Üç Nokta ( … ) – 4. kullanım', 'Sözün bir yerde kesilerek geri kalan bölümün okuyucunun hayal dünyasına bırakıldığını göstermek veya ifadeye güç katmak için konur', 'Sana uğurlar olsun… Ayrılıyor yolumuz! (Faruk Nafiz Çamlıbel)\nBinaenaleyh, biz her vasıtadan, yalnız ve ancak, bir noktainazardan istifade ederiz. O noktainazar şudur: Türk milletini, medeni cihanda layık olduğu mevkiye isat etmek ve Türk cumhuriyetini sarsılmaz temelleri üzerinde, her gün, daha ziyade takviye etmek… (Atatürk)'],
      ['Üç Nokta ( … ) – 5. kullanım', 'Ünlem ve seslenmelerde anlatımı pekiştirmek için konur', 'Gölgeler yaklaştılar. Bir adım kalınca onu kıyafetinden tanıdılar:\n—      Koca Ali… Koca Ali, be!.. (Ömer Seyfettin)'],
      ['Üç Nokta ( … ) – Uyarı 1', 'Ünlem ve soru işaretinden sonra üç nokta yerine iki nokta konulması yeterlidir', 'Gök ekini biçer gibi!.. Başaklar daha dolmadan. (Tarık Buğra)\nNasıl da akşam oldu?.. Nasıl da yavrucaklar sustu?.. Nasıl da serçecikler yuvalarına sığındı?.. (Necip Fazıl Kısakürek)'],
      ['Üç Nokta ( … ) – 6. kullanım', 'Karşılıklı konuşmalarda, yeterli olmayan, eksik bırakılan cevaplarda kullanılır', '— Yabancı yok!\n— Kimsin?\n— Ali…'],
      ['Üç Nokta ( … ) – Uyarı 2', 'Üç nokta yerine iki veya daha çok nokta kullanılmaz.', ''],
      ['Soru İşareti ( ? ) – 1. kullanım', 'Soru eki veya sözü içeren cümle veya sözlerin sonuna konur', 'Ne zaman tükenecek bu yollar, arabacı? (Faruk Nafiz Çamlıbel)\nAtatürk bana sordu:\n— Yeni yazıyı tatbik etmek için ne düşündünüz? (Falih Rıfkı Atay)'],
      ['Soru İşareti ( ? ) – 2. kullanım', 'Soru bildiren ancak soru eki veya sözü içermeyen cümlelerin sonuna konur', 'Gümrükteki memur başını kaldırdı:\n— Adınız?'],
      ['Soru İşareti ( ? ) – 3. kullanım', 'Bilinmeyen, kesin olmayan veya şüpheyle karşılanan yer, tarih vb. durumlar için kullanılır', 'Yunus Emre (1240 ?-1320), (Doğum yeri: ?) vb.\n1496 (?) yılında doğan Fuzuli…\nAnkara’dan Antalya’ya arabayla üç saatte (?) gitmiş.'],
      ['Soru İşareti ( ? ) – Uyarı 1', 'mı / mi ekini alan yan cümle temel cümlenin zarf tümleci olduğunda cümlenin sonuna soru işareti konmaz: Akşam oldu mu sürüler döner. Hava karardı mı eve gideriz.', 'Bahar gelip de nehir çağıl çağıl kabarmaya başlamaz mı içimi geri kalmış bir saat huzursuzluğu kaplardı. (Haldun Taner)'],
      ['Soru İşareti ( ? ) – Uyarı 2', 'Soru ifadesi taşıyan sıralı ve bağlı cümlelerde soru işareti en sona konur', 'Çok yakından mı bu sesler, çok uzaklardan mı?\nÜsküdar’dan mı, Hisar’dan mı, Kavaklardan mı? (Yahya Kemal Beyatlı)'],
      ['Ünlem İşareti ( ! ) – 1. kullanım', 'Sevinç, kıvanç, acı, korku, şaşma gibi duyguları anlatan cümle veya ibarelerin sonuna konur', 'Hava ne kadar da sıcak! Aşk olsun! Ne kadar akıllı adamlar var! Vah vah!\nNe mutlu Türk’üm diyene! (Atatürk)'],
      ['Ünlem İşareti ( ! ) – 2. kullanım', 'Seslenme, hitap ve uyarı sözlerinden sonra konur', 'Ordular! İlk hedefiniz Akdeniz’dir, ileri! (Atatürk)\nEy Türk gençliği! Birinci vazifen; Türk istiklalini, Türk cumhuriyetini, ilelebet, muhafaza ve müdafaa etmektir. (Atatürk)\nAk tolgalı beylerbeyi haykırdı: İlerle! (Yahya Kemal Beyatlı)'],
      ['Ünlem İşareti ( ! ) – Uyarı 1', 'Ünlem işareti, seslenme ve hitap sözlerinden hemen sonra konulabileceği gibi cümlenin sonuna da konabilir', 'Arkadaş, biz bu yolda türküler tuttururken\nSana uğurlar olsun… Ayrılıyor yolumuz! (Faruk Nafiz Çamlıbel)'],
      ['Ünlem İşareti ( ! ) – 3. kullanım', 'Alay, kinaye veya küçümseme anlamı kazandırılmak istenen sözden hemen sonra yay ayraç içinde ünlem işareti kullanılır', 'İsteseymiş bir günde bitirirmiş (!) ama ne yazık ki vakti yokmuş (!).\nAdam, akıllı (!) olduğunu söylüyor.'],
      ['Kısa Çizgi ( – ) – 1. kullanım', 'Satıra sığmayan kelimeler bölünürken satır sonuna konur', 'Soğuktan mı titriyordum, yoksa heyecandan, üzüntüden mi bil-\nmem. Havuzun suyu bulanık. Kapının saatleri 12’yi geçmiş. Kanepe-\nlerde kimseler yok. Tramvay ne fena gıcırdadı! Tramvayda-'],
      ['Kısa Çizgi ( – ) – 2. kullanım', 'Cümle içinde ara sözleri veya ara cümleleri ayırmak için ara sözlerin veya ara cümlelerin başına ve sonuna konur, bitişik yazılır', 'Küçük bir sürü -dört inekle birkaç koyun- köye giren geniş yolun ağzında durmuştu. (Ömer Seyfettin)'],
      ['Kısa Çizgi ( – ) – 3. kullanım', 'Kelimelerin kökleri, gövdeleri ve eklerini birbirinden ayırmak için kullanılır', 'al-ış, dur-ak, gör-gü-süz-lük vb.'],
      ['Kısa Çizgi ( – ) – 4. kullanım', 'Fiil kök ve gövdelerini göstermek için kullanılır', 'al-, dur-, gör-, ver-; başar-, kana-, okut-, taşla-, yazdır- vb.'],
      ['Kısa Çizgi ( – ) – 5. kullanım', 'İsim yapma eklerinin başına, fiil yapma eklerinin başına ve sonuna konur', '-ak, -den, -ış, -lık; -ımsa-; -la-; -tır- vb.'],
      ['Kısa Çizgi ( – ) – 6. kullanım', 'Heceleri göstermek için kullanılır', 'a-raş-tır-ma, bi-le-zik, du-ruş-ma, ku-yum-cu-luk, prog-ram, ya-zar-lık vb.'],
      ['Kısa Çizgi ( – ) – 7. kullanım', 'Arasında, ve, ile, ila, …-den …-e anlamlarını vermek için kelimeler veya sayılar arasında kullanılır', 'Aydın-İzmir yolu, Türk-Alman ilişkileri, Ural-Altay dil grubu, Dil ve Tarih-Coğrafya Fakültesi, 09.30-10.30, Beşiktaş-Fenerbahçe karşılaşması, Manas Destanı’nda soy-dil-din üçgeni, 1914-1918 Birinci Dünya Savaşı, Türkçe-Fransızca Sözlük vb.'],
      ['Kısa Çizgi ( – ) – Uyarı 1', 'Cümle içinde sayı adlarının yinelenmesinde araya kısa çizgi konmaz: On on beş yıl. Üç beş kişi geldi.', ''],
      ['Kısa Çizgi ( – ) – 8. kullanım', 'Matematikte çıkarma işareti olarak kullanılır', '50-20=30'],
      ['Kısa Çizgi ( – ) – 9. kullanım', 'Sıfırdan küçük değerleri göstermek için kullanılır', '-2 °C'],
      ['Uzun Çizgi (—) – Uyarı 1', 'Konuşmalar tırnak içinde verildiğinde uzun çizgi kullanılmaz.', 'Arabamız tutarken Erciyes’in yolunu:\n“Hancı dedim, bildin mi Maraşlı Şeyhoğlu’nu?” (Faruk Nafiz Çamlıbel)'],
      ['Eğik Çizgi ( / ) – 1. kullanım', 'Dizeler yan yana yazıldığında aralarına konur', 'Korkma! Sönmez bu şafaklarda yüzen al sancak / Sönmeden yurdumun üstünde tüten en son ocak / O benim milletimin yıldızıdır, parlayacak / O benimdir, o benim milletimindir ancak. (Mehmet Akif Ersoy)'],
      ['Eğik Çizgi ( / ) – 2. kullanım', 'Adres yazarken apartman numarası ile daire numarası arasına ve semt ile şehir arasına konur', 'Altay Sokağı No.: 21/6 Kurtuluş / ANKARA\nÜlke adı yazılacağında ise:\nAtatürk Bulvarı No.: 217'],
      ['Eğik Çizgi ( / ) – 3. kullanım', 'Tarihlerin yazılışında gün, ay ve yılı gösteren sayıları birbirinden ayırmak için konur', '18/11/1969, 15/IX/1994 vb.'],
      ['Eğik Çizgi ( / ) – 4. kullanım', 'Dil bilgisinde eklerin farklı biçimlerini göstermek için kullanılır', '-a /-e, -an /-en, -lık /-lik, -madan /-meden vb.'],
      ['Eğik Çizgi ( / ) – 5. kullanım', 'Genel ağ adreslerinde kullanılır', 'http://tdk.gov.tr'],
      ['Eğik Çizgi ( / ) – 6. kullanım', 'Matematikte bölme işareti olarak kullanılır', '70/2=35'],
      ['Eğik Çizgi ( / ) – 7. kullanım', 'Fizik, matematik vb. alanlarda birimler arası orantıları gösterirken eğik çizgi araya boşluk konulmadan kullanılır', 'g/sn (gram/saniye)'],
      ['Tırnak İşareti ( “ ” ) – 1. kullanım', 'Başka bir kimseden veya yazıdan olduğu gibi aktarılan sözler tırnak içine alınır', 'Türk Dil Kurumu binasının yan cephesinde Atatürk’ün “Türk dili, Türk milletinin kalbidir, zihnidir.” sözü yazılıdır. Dil ve Tarih-Coğrafya Fakültesinin ön cephesinde Atatürk’ün “Hayatta en hakiki mürşit ilimdir.” vecizesi yer almaktadır. Ulu önderin “Ne mutlu Türk’üm diyene!” sözü her Türk’ü duygulandırır.\nBakınız, şair vatanı ne güzel tarif ediyor:\n“Bayrakları bayrak yapan üstündeki kandır.'],
      ['Tırnak İşareti ( “ ” ) – Uyarı 1', 'Tırnak içindeki alıntının sonunda bulunan işaret (nokta, soru işareti, ünlem işareti vb.) tırnak içinde kalır', '“İzmir üzerine dünyada bir şehir daha yoktur!” diyorlar. (Yahya Kemal Beyatlı)'],
      ['Tırnak İşareti ( “ ” ) – 2. kullanım', 'Özel olarak vurgulanmak istenen sözler tırnak içine alınır', 'Yeni bir “barış taarruzu” başladı.'],
      ['Tırnak İşareti ( “ ” ) – 3. kullanım', 'Cümle içerisinde eserlerin ve yazıların adları ile bölüm başlıkları tırnak içine alınır', 'Bugün öğrenciler “Kendi Gök Kubbemiz” adlı şiiri incelediler.\n“Yazım Kuralları” bölümünde bazı uyarılara yer verilmiştir.'],
      ['Tırnak İşareti ( “ ” ) – Uyarı 2', 'Cümle içerisinde özel olarak belirtilmek istenen sözler, kitap ve dergi adları ve başlıkları tırnak içine alınmaksızın eğik yazıyla dizilerek de gösterilebilir', 'Höyük sözü Anadolu’da tepe olarak geçer.\nCahit Sıtkı’nın Şairin Ölümü şiirini Yahya Kemal çok sevmişti. (Ahmet Hamdi Tanpınar)'],
      ['Tırnak İşareti ( “ ” ) – Uyarı 3', 'Tırnak içine alınan sözlerden sonra gelen ekleri ayırmak için kesme işareti kullanılmaz: Elif Şafak’ın “Bit Palas”ını okudunuz mu?', ''],
      ['Tırnak İşareti ( “ ” ) – 4. kullanım', 'Bilimsel çalışmalarda künye verilirken makale adları tırnak içinde yazılır.', ''],
      ['Yay Ayraç ( ) – 1. kullanım', 'Cümledeki anlamı tamamlayan ve cümlenin dışında kalan ek bilgiler için kullanılır. Yay ayraç içinde bulunan ve yargı bildiren anlatımların sonuna uygun noktalama işareti konur', 'Anadolu kentlerini, köylerini (Köy sözünü de çekinerek yazıyorum.) gezsek bile görmek için değil, kendimizi göstermek için geziyoruz. (Nurullah Ataç)'],
      ['Yay Ayraç ( ) – 2. kullanım', 'Özel veya cins isme ait ek, ayraçtan önce yazılır', 'Yunus Emre’nin (1240?-1320)…\nİmek fiilinin (ek fiil) geniş zamanı şahıs ekleriyle çekilir.'],
      ['Yay Ayraç ( ) – 3. kullanım', 'Tiyatro eserlerinde ve senaryolarda konuşanın hareketlerini, durumunu açıklamak ve göstermek için kullanılır', 'İhtiyar – (Yavaş yavaş Kaymakam’a yaklaşır.) Ne oluyor beyefendi? Allah rızası için bana da anlatın… (Reşat Nuri Güntekin)'],
      ['Yay Ayraç ( ) – 4. kullanım', 'Alıntıların aktarıldığı eseri, yazarı veya künye bilgilerini göstermek için kullanılır', 'Cihanın tarihi, vatanı uğrunda senin kadar uğraşan, kanını döken bir millet daha gösteremez. Senin kadar kimse kendi vatanına sahip olmaya hak kazanmamıştır. Bu vatan ya senindir ya kimsenin. (Ahmet Hikmet Müftüoğlu)\nEşin var, aşiyanın var, baharın var ki beklerdin\nKıyametler koparmak neydi ey bülbül, nedir derdin? (Mehmet Akif Ersoy)'],
      ['Yay Ayraç ( ) – 5. kullanım', 'Alıntılarda, alınmayan kelime veya bölümlerin yerine konulan üç nokta, yay ayraç içine alınabilir.', '(…)'],
      ['Yay Ayraç ( ) – 6. kullanım', 'Bir söze alay, kinaye veya küçümseme anlamı kazandırmak için kullanılan ünlem işareti yay ayraç içine alınır', 'Adam, akıllı (!) olduğunu söylüyor.'],
      ['Yay Ayraç ( ) – 7. kullanım', 'Bir bilginin şüpheyle karşılandığını veya kesin olmadığını göstermek için kullanılan soru işareti yay ayraç içine alınır', '1496 (?) yılında doğan Fuzuli…'],
      ['Yay Ayraç ( ) – 8. kullanım', 'Bir yazının maddelerini gösteren sayı ve harflerden sonra kapama ayracı konur', 'I)             1)                   A)           a)\nII)           2)                    B)           b)'],
      ['Köşeli Ayraç ( [ ] ) – 1. kullanım', 'Ayraç içinde ayraç kullanılması gereken durumlarda yay ayraçtan önce köşeli ayraç kullanılır', 'Halikarnas Balıkçısı [Cevat Şakir Kabaağaçlı (1886-1973)] en güzel eserlerini Bodrum’da yazmıştır.'],
      ['Köşeli Ayraç ( [ ] ) – 2. kullanım', 'Metin aktarmalarında, çevirilerde, alıntılarda çalışmayı yapanın eklediği sözler için kullanılır', '“Eldem, Osmanlıda en önemli fark[ın], mezar taşının şeklinde ortaya çık[tığını] söyledikten sonra…” (Hilmi Yavuz)'],
      ['Köşeli Ayraç ( [ ] ) – 3. kullanım', 'Kaynak olarak verilen kitap veya makalelerin künyelerine ilişkin bazı ayrıntıları göstermek için kullanılır', 'Reşat Nuri [Güntekin], Çalıkuşu, Dersaadet, 1922. Server Bedi [Peyami Safa]'],
      ['Kesme İşareti ( ’ ) – 1. kullanım', 'Özel adlara getirilen iyelik, durum ve bildirme ekleri kesme işaretiyle ayrılır', 'Kurtuluş Savaşı’nı, Atatürk’üm, Türkiye’mizin, Fatih Sultan Mehmet’e, Muhibbi’nin, Gül Baba’ya, Sultan Ana’nın, Mehmet Emin Yurdakul’dan, Kâzım Karabekir’i, Yunus Emre’yi, Ziya Gökalp’tan, Refik Halit Karay’mış, Ahmet Cevat Emre’dir, Namık Kemal’se, Şinasi’yle, Alman’sınız, Kırgız’ım, Karakeçili’nin, Osmanlı Devleti’ndeki, Cebrail’den, Çanakkale Boğazı’nın, Samanyolu’nda, Sait Halim Paşa Yalısı’ndan, Resmî Gazete’de,…'],
      ['Kesme İşareti ( ’ ) – Uyarı 1', 'Sonunda 3. teklik kişi iyelik eki olan özel ada, bu ek dışında başka bir iyelik eki getirildiğinde kesme işareti konmaz', 'Boğaz Köprümüzün güzelliği, Amik Ovamızın bitki örtüsü, Kuşadamızdaki liman vb.'],
