    StudyTopicDef('dil_en.5', 'Fiil biçimleri ve sık hatalar', [
      ['-ed kuralı: Çoğu fiil', 'sona -ed ekle', 'work → worked, play → played'],
      ['-ed kuralı: -e ile bitiyorsa', 'sadece -d ekle', 'live → lived, use → used'],
      ['-ed kuralı: ünsüz + y ile bitiyorsa', 'y düşer, -ied olur', 'study → studied, try → tried'],
      ['-ed kuralı: ünlü + y ile bitiyorsa', 'y kalır, -ed eklenir', 'play → played, stay → stayed'],
      ['-ed kuralı: Tek heceli, ünsüz-ünlü-ünsüz', 'son harf ikilenir + ed', 'stop → stopped, plan → planned'],
      ['-ed kuralı: Vurgu son hecedeyse', 'son harf ikilenir + ed', 'prefer → preferred'],
      ['-ed kuralı: -l ile bitiyorsa', 'İngiliz İng.: l ikilenir; Amerikan İng.: ikilenmez', 'travel → travelled (UK) / traveled (US)'],
      ['-ed okunuşu /t/ ("t")', 'Sessiz (titreşimsiz) seslerden sonra: p, k, s, ʃ (sh), tʃ (ch), f', 'worked ("workt"), stopped, watched, washed'],
      ['-ed okunuşu /d/ ("d")', 'Sesli (titreşimli) seslerden ve ünlülerden sonra', 'played ("pleyd"), lived, called, opened'],
      ['-ed okunuşu /ɪd/ ("id")', 'Fiil t veya d sesiyle bitiyorsa', 'wanted ("wantid"), needed, started, decided'],
      ['Yapı: Geniş zaman', 'Formül: V1 (he/she/it: V1+s)\nTürkçe: E-posta yazar.', 'She writes emails.'],
      ['Yapı: Şimdiki zaman', 'Formül: am/is/are + V1-ing\nTürkçe: Şu an yazıyor.', 'She is writing now.'],
      ['Yapı: Gelecek zaman', 'Formül: will + V1\nTürkçe: Onu yazacak.', 'She will write it.'],
      ['Yapı: Geçmiş zaman (+)', 'Formül: V2\nTürkçe: Bir mektup yazdı.', 'She wrote a letter.'],
      ['Yapı: Geçmiş zaman (–)', 'Formül: didn\'t + V1\nTürkçe: Onu yazmadı.', 'She didn\'t write it.'],
      ['Yapı: Geçmiş zaman (?)', 'Formül: Did + özne + V1?\nTürkçe: Onu yazdı mı?', 'Did she write it?'],
      ['Yapı: Present perfect', 'Formül: have/has + V3\nTürkçe: Bir kitap yazdı (yazmış).', 'She has written a book.'],
      ['Yapı: Past perfect', 'Formül: had + V3\nTürkçe: Onu daha önce yazmıştı.', 'She had written it before.'],
      ['Yapı: Edilgen (passive)', 'Formül: be + V3\nTürkçe: 1990\'da yazıldı.', 'It was written in 1990.'],
      ['Yapı: Sıfat olarak', 'Formül: V3 + isim\nTürkçe: yazılı sınav', 'a written exam'],
      ['Hata bul: I goed to school.', 'Doğrusu: I went to school.', 'go düzensizdir.'],
      ['Hata bul: I didn\'t went.', 'Doğrusu: I didn\'t go.', 'did\'den sonra V1.'],
      ['Hata bul: Did you saw him?', 'Doğrusu: Did you see him?', 'Soruda did + V1.'],
      ['Hata bul: I have saw it.', 'Doğrusu: I have seen it.', 'have\'den sonra V3.'],
      ['Hata bul: It was broke.', 'Doğrusu: It was broken.', 'Edilgende V3.'],
      ['Hata bul: She buyed a car.', 'Doğrusu: She bought a car.', 'buy düzensizdir.'],
      ['Hata bul: He studyed.', 'Doğrusu: He studied.', 'ünsüz + y → -ied.'],
    ]),
    StudyTopicDef('dil_en.6', 'Zamirler', [
      ['Ben → I', 'Nesne: me\nİyelik sıfatı: my\nİyelik zamiri: mine\nDönüşlü: myself', ''],
      ['Sen → you', 'Nesne: you\nİyelik sıfatı: your\nİyelik zamiri: yours\nDönüşlü: yourself', ''],
      ['O (erkek) → he', 'Nesne: him\nİyelik sıfatı: his\nİyelik zamiri: his\nDönüşlü: himself', ''],
      ['O (kadın) → she', 'Nesne: her\nİyelik sıfatı: her\nİyelik zamiri: hers\nDönüşlü: herself', ''],
      ['O (nesne/hayvan) → it', 'Nesne: it\nİyelik sıfatı: its\nİyelik zamiri: —\nDönüşlü: itself', ''],
      ['Biz → we', 'Nesne: us\nİyelik sıfatı: our\nİyelik zamiri: ours\nDönüşlü: ourselves', ''],
      ['Siz → you', 'Nesne: you\nİyelik sıfatı: your\nİyelik zamiri: yours\nDönüşlü: yourselves', ''],
      ['Onlar → they', 'Nesne: them\nİyelik sıfatı: their\nİyelik zamiri: theirs\nDönüşlü: themselves', ''],
      ['İyelik sıfatı ve iyelik zamiri farkı', 'İyelik sıfatı isimle birlikte kullanılır (my book); iyelik zamiri tek başına durur (mine).', 'It is my book. → It is mine.\nThat is your seat. → That is yours.'],
      ['this / that / these / those', 'Yakın: this (tekil), these (çoğul). Uzak: that (tekil), those (çoğul).', ''],
      ['Soru zamiri: who', 'kim (özne)', 'Who called? — Kim aradı?'],
      ['Soru zamiri: whom', 'kimi, kime (resmî)', 'Whom did you see? — Kimi gördün?'],
      ['Soru zamiri: whose', 'kimin', 'Whose bag is this? — Bu kimin çantası?'],
      ['Soru zamiri: what', 'ne', 'What happened? — Ne oldu?'],
      ['Soru zamiri: which', 'hangisi (seçenekler arasından)', 'Which do you prefer? — Hangisini tercih edersin?'],
      ['İlgi zamiri: who', 'insanlar', 'The man who lives here is a doctor. — Burada yaşayan adam doktor.'],
      ['İlgi zamiri: which', 'nesneler, hayvanlar', 'The car which I bought is red. — Aldığım araba kırmızı.'],
      ['İlgi zamiri: that', 'insan ve nesne (gayriresmî)', 'The book that you gave me is great. — Bana verdiğin kitap harika.'],
      ['İlgi zamiri: whose', 'sahiplik', 'The girl whose father is a pilot... — Babası pilot olan kız...'],
      ['İlgi zamiri: whom', 'insan (nesne, resmî)', 'The person whom I met... — Tanıştığım kişi...'],
      ['some- ile biçimler', 'Kişi: someone — biri\nŞey: something — bir şey\nYer: somewhere — bir yer', ''],
      ['any- ile biçimler', 'Kişi: anyone — herhangi biri\nŞey: anything — herhangi bir şey\nYer: anywhere — herhangi bir yer', ''],
      ['no- ile biçimler', 'Kişi: no one / nobody — hiç kimse\nŞey: nothing — hiçbir şey\nYer: nowhere — hiçbir yer', ''],
      ['every- ile biçimler', 'Kişi: everyone — herkes\nŞey: everything — her şey\nYer: everywhere — her yer', ''],
      ['Hata bul: Is very good.', 'Doğrusu: It is very good.', 'Özne düşürülemez.'],
      ['Hata bul: My sister, he is a nurse.', 'Doğrusu: My sister, she is a nurse.', 'Kadın için she.'],
      ['Hata bul: Me and Ali went home.', 'Doğrusu: Ali and I went home.', 'Öznede I; kibarlık için kendini sona koy.'],
      ['Hata bul: Give it to I.', 'Doğrusu: Give it to me.', 'Edattan sonra nesne zamiri.'],
      ['Hata bul: This is my.', 'Doğrusu: This is mine.', 'Tek başına iyelik zamiri.'],
      ['Hata bul: The dog wagged it\'s tail.', 'Doğrusu: The dog wagged its tail.', 'it\'s = it is; iyelik: its.'],
      ['Hata bul: Their going home.', 'Doğrusu: They\'re going home.', 'they\'re = they are; their = onların; there = orada.'],
      ['Hata bul: Everybody are happy.', 'Doğrusu: Everybody is happy.', 'Belgisiz zamir tekil.'],
    ]),
    StudyTopicDef('dil_en.7', 'Edatlar (in, at, on, to)', [
      ['\'in\' ne zaman kullanılır?', 'Kapalı bir alanın içi: in the box, in the room, in the car — kutuda, odada, arabada\nŞehir, ülke, bölge: in İstanbul, in Turkey, in Europe\nAy, yıl, mevsim, yüzyıl: in May, in 2026, in summer, in the 21st century\nGünün bölümleri: in the morning, in the afternoon, in the evening\nBelirli süre sonra: in 10 minutes — 10 dakika içinde/sonra\nKalıplar: in time (vaktinde), in English, in love, in a hurry', ''],
      ['\'at\' ne zaman kullanılır?', 'Belirli bir nokta / adres: at the door, at the bus stop, at 15 Atatürk Street\nEtkinlik veya kurum (orada bulunmak): at school, at work, at home, at a party\nSaat: at 5 o\'clock, at noon, at midnight\nBelirli zaman noktaları: at night, at the weekend (İng.), at the moment, at Christmas\nHedef / yöneliş (bakmak, gülmek...): look at, laugh at, point at, good at', ''],
      ['\'on\' ne zaman kullanılır?', 'Yüzeyin üstü: on the table, on the wall, on the floor\nGün ve tarih: on Monday, on 29 October, on my birthday\nUlaşım (büyük araçlar): on the bus, on the train, on a plane', ''],
      ['Zaman için IN', 'geniş dilim: ay, yıl, mevsim', 'in June, in 2025'],
      ['Zaman için ON', 'gün, tarih', 'on Friday, on 1 May'],
      ['Zaman için AT', 'saat, dar nokta', 'at 9:00, at night'],
      ['\'to\' ne zaman kullanılır?', 'Bir yere doğru hareket: go to school, come to my house, walk to the park — okula git...\nAlıcı (birine vermek, söylemek): give it to me, talk to her, send it to them — bana ver, onunla konuş...\nAralık (-den ... -e): from 9 to 5, from Ankara to İzmir\nSaat söylerken (kala): ten to six — altıya on var\nMastar eki (edat değil!): I want to eat. — Yemek istiyorum. (to + fiil yalın hâli)', ''],
      ['Edat seçimi: Bir yere gidiyorsan (hareket)', 'to', 'I\'m going to the office. — Ofise gidiyorum.'],
      ['Edat seçimi: Bir noktada bulunuyorsan', 'at', 'I\'m at the office. — Ofisteyim.'],
      ['Edat seçimi: Bir yerin içinde olduğunu vurguluyorsan', 'in', 'He is in the office. — Ofisin içinde.'],
      ['Edat seçimi: Varış (arrive)', 'at / in', 'arrive at the airport, arrive in İstanbul (asla arrive to)'],
      ['Hata bul: I go to home.', 'Doğrusu: I go home.', 'home ile to kullanılmaz.'],
      ['Hata bul: in Monday', 'Doğrusu: on Monday', 'Günlerle on.'],
      ['Hata bul: at 2026', 'Doğrusu: in 2026', 'Yıllarla in.'],
      ['Hata bul: in 7 o\'clock', 'Doğrusu: at 7 o\'clock', 'Saatle at.'],
      ['Hata bul: I arrived to Ankara.', 'Doğrusu: I arrived in Ankara.', 'arrive + in/at.'],
      ['Hata bul: Listen me.', 'Doğrusu: Listen to me.', 'listen daima to ister.'],
      ['Hata bul: Look me.', 'Doğrusu: Look at me.', 'look (bakmak) + at.'],
      ['Hata bul: Give it to I.', 'Doğrusu: Give it to me.', 'Edattan sonra nesne zamiri.'],
    ]),
    StudyTopicDef('dil_en.8', 'Zamanlar: genel bakış', [
      ['Present zamanlar', 'Simple: I work\nContinuous: I am working\nPerfect: I have worked\nPerfect Continuous: I have been working', ''],
      ['Past zamanlar', 'Simple: I worked\nContinuous: I was working\nPerfect: I had worked\nPerfect Continuous: I had been working', ''],
      ['Future zamanlar', 'Simple: I will work\nContinuous: I will be working\nPerfect: I will have worked\nPerfect Continuous: I will have been working', ''],
      ['Simple (zaman türü)', 'Genel gerçek, alışkanlık, tek seferlik olay', 'Yapı taşı: V1 / V2 / will + V1'],
      ['Continuous (zaman türü)', 'Belli bir anda devam eden eylem', 'Yapı taşı: be + V-ing'],
      ['Perfect (zaman türü)', 'Bir noktadan önce tamamlanmış eylem', 'Yapı taşı: have + V3'],
      ['Perfect Continuous (zaman türü)', 'Bir noktaya kadar süregelen eylem (süre vurgusu)', 'Yapı taşı: have been + V-ing'],
      ['Present Simple', 'Formül: V1 / V1+s\nTürkçe: Geniş zaman (-r)', 'I drink tea. — Çay içerim.'],
      ['Present Continuous', 'Formül: am/is/are + V-ing\nTürkçe: Şimdiki zaman (-yor)', 'I am drinking tea. — Çay içiyorum.'],
      ['Past Simple', 'Formül: V2\nTürkçe: Görülen geçmiş (-dı)', 'I drank tea. — Çay içtim.'],
      ['Past Continuous', 'Formül: was/were + V-ing\nTürkçe: Şimdiki zamanın hikâyesi (-yordu)', 'I was drinking tea. — Çay içiyordum.'],
      ['Present Perfect', 'Formül: have/has + V3\nTürkçe: -dı / -mış (etkisi şimdi)', 'I have drunk tea. — Çay içtim (içmiş bulunuyorum).'],
      ['Present Perfect Cont.', 'Formül: have/has been + V-ing\nTürkçe: -dır ...-yor', 'I have been drinking tea for an hour. — Bir saattir çay içiyorum.'],
      ['Past Perfect', 'Formül: had + V3\nTürkçe: -mıştı', 'I had drunk tea. — Çay içmiştim.'],
      ['Past Perfect Cont.', 'Formül: had been + V-ing\nTürkçe: -dır ...-yordu', 'I had been drinking tea. — (O zamana kadar) çay içiyordum.'],
      ['Future Simple', 'Formül: will + V1\nTürkçe: Gelecek zaman (-acak)', 'I will drink tea. — Çay içeceğim.'],
      ['Be going to', 'Formül: am/is/are going to + V1\nTürkçe: -acak (planlı)', 'I am going to drink tea. — Çay içeceğim (niyetim var).'],
      ['Future Continuous', 'Formül: will be + V-ing\nTürkçe: -ıyor olacak', 'I will be drinking tea. — Çay içiyor olacağım.'],
      ['Future Perfect', 'Formül: will have + V3\nTürkçe: -mış olacak', 'I will have drunk tea. — Çay içmiş olacağım.'],
    ]),
    StudyTopicDef('dil_en.9', 'Zamanlar: yapılar ve kullanım', [
      ['Present Simple: yapı', 'Olumlu (+)  I/you/we/they + V1 he/she/it + V1-s\nOlumsuz (–)  don\'t / doesn\'t + V1\nSoru (?)  Do / Does + özne + V1?', 'She works in a bank. — Bankada çalışır.\nShe doesn\'t work on Sundays. — Pazar çalışmaz.\nDoes she work here? — Burada mı çalışıyor?'],
      ['Present Simple ne zaman kullanılır?', '• Alışkanlık, rutin\n• Genel / bilimsel gerçek\n• Kalıcı durum\n• Tarife, program (gelecek anlamlı)\n• Durum fiilleri (know, like, want...)', 'I get up at 7 every day. — Her gün 7\'de kalkarım.\nWater boils at 100°C. — Su 100 derecede kaynar.\nThey live in Bursa. — Bursa\'da yaşıyorlar.\nThe train leaves at 9:30. — Tren 9:30\'da kalkar.\nI know him. — Onu tanıyorum.'],
      ['Present Continuous: yapı', 'Olumlu (+)  am / is / are + V-ing\nOlumsuz (–)  am not / isn\'t / aren\'t + V-ing\nSoru (?)  Am / Is / Are + özne + V-ing?', 'I am reading a book. — Kitap okuyorum.\nHe isn\'t sleeping. — Uyumuyor.\nAre you listening? — Dinliyor musun?'],
      ['Present Continuous ne zaman kullanılır?', '• Konuşma anında olan\n• Bu aralar süren geçici durum\n• Kesin, ayarlanmış yakın gelecek planı\n• Değişen, gelişen durum\n• always ile şikâyet', 'It is raining now. — Şu an yağmur yağıyor.\nI am studying for an exam these days. — Bu aralar bir sınava çalışıyorum.\nI am meeting Ali tomorrow. — Yarın Ali\'yle buluşuyorum.\nPrices are rising. — Fiyatlar yükseliyor.\nHe is always losing his keys! — Hep anahtarlarını kaybediyor!'],
      ['Past Simple: yapı', 'Olumlu (+)  V2 (düzenli: V1+ed)\nOlumsuz (–)  didn\'t + V1\nSoru (?)  Did + özne + V1?', 'We visited Konya last year. — Geçen yıl Konya\'yı ziyaret ettik.\nI didn\'t see him. — Onu görmedim.\nDid you call her? — Onu aradın mı?'],
      ['Past Simple ne zaman kullanılır?', '• Zamanı belli, bitmiş olay\n• Geçmişte art arda olaylar\n• Geçmiş alışkanlık\n• was / were (be fiili)', 'I bought this car in 2020. — Bu arabayı 2020\'de aldım.\nHe came home, ate dinner and slept. — Eve geldi, yedi, uyudu.\nI walked to school every day. — Her gün okula yürürdüm.\nIt was cold. They were at home. — Hava soğuktu. Evdeydiler.'],
      ['Past Continuous: yapı', 'Olumlu (+)  was / were + V-ing\nOlumsuz (–)  wasn\'t / weren\'t + V-ing\nSoru (?)  Was / Were + özne + V-ing?', 'I was watching TV at 9. — Saat 9\'da TV izliyordum.\nThey weren\'t working. — Çalışmıyorlardı.\nWas it raining? — Yağmur yağıyor muydu?'],
      ['Past Continuous ne zaman kullanılır?', '• Geçmişte belli bir anda süren\n• Süren eylemi kesen kısa olay (when)\n• Aynı anda süren iki eylem (while)\n• Hikâyede arka plan', 'At 8 pm I was cooking. — Akşam 8\'de yemek yapıyordum.\nI was sleeping when the phone rang. — Telefon çaldığında uyuyordum.\nWhile I was reading, she was cooking. — Ben okurken o yemek yapıyordu.\nThe sun was shining and birds were singing.'],
      ['Present Perfect: yapı', 'Olumlu (+)  have / has + V3\nOlumsuz (–)  haven\'t / hasn\'t + V3\nSoru (?)  Have / Has + özne + V3?', 'I have finished my work. — İşimi bitirdim.\nShe hasn\'t arrived yet. — Henüz gelmedi.\nHave you ever been to Paris? — Hiç Paris\'e gittin mi?'],
      ['Present Perfect ne zaman kullanılır?', '• Hayat tecrübesi (zaman belirtilmez)\n• Yeni olmuş, sonucu şimdi önemli\n• Geçmişte başlayıp hâlâ süren (for/since)\n• Henüz bitmemiş zaman dilimi\n• just / already / yet', 'I have visited Italy twice. — İtalya\'ya iki kez gittim.\nI have lost my keys. — Anahtarlarımı kaybettim (şu an yok).\nWe have lived here for 10 years. — 10 yıldır burada yaşıyoruz.\nI have drunk 3 coffees today. — Bugün 3 kahve içtim.\nHe has just left. — Az önce çıktı.'],
      ['Present Perfect Continuous: yapı', 'Olumlu (+)  have / has been + V-ing\nOlumsuz (–)  haven\'t / hasn\'t been + V-ing\nSoru (?)  Have / Has + özne + been + V-ing?', 'I have been waiting for an hour. — Bir saattir bekliyorum.\nHe hasn\'t been sleeping well. — İyi uyuyamıyor (bir süredir).\nHow long have you been learning English? — Ne kadar zamandır İngilizce öğreniyorsun?'],
      ['Present Perfect Continuous ne zaman kullanılır?', '• Süreyi vurgulamak\n• Şu anki sonucun sebebi', 'She has been working since 8. — 8\'den beri çalışıyor.\nI\'m tired. I have been running. — Yorgunum, koşuyordum.'],
      ['Past Perfect: yapı', 'Olumlu (+)  had + V3\nOlumsuz (–)  hadn\'t + V3\nSoru (?)  Had + özne + V3?', 'The film had started when we arrived. — Vardığımızda film başlamıştı.\nI hadn\'t eaten sushi before. — Daha önce suşi yememiştim.\nHad you met him before? — Onunla daha önce tanışmış mıydın?'],
      ['Past Perfect ne zaman kullanılır?', '• İki geçmiş olaydan önce olanı\n• Geçmişteki bir ana kadarki tecrübe\n• Dolaylı anlatım', 'When I got to the station, the train had left. — İstasyona vardığımda tren gitmişti.\nBy 2010, she had visited 20 countries. — 2010\'a kadar 20 ülke gezmişti.\nHe said he had finished. — Bitirdiğini söyledi.'],
      ['Past Perfect Continuous: yapı', 'Olumlu (+)  had been + V-ing\nOlumsuz (–)  hadn\'t been + V-ing\nSoru (?)  Had + özne + been + V-ing?', 'I had been waiting for 2 hours when he came. — O geldiğinde 2 saattir bekliyordum.\nShe hadn\'t been feeling well. — (Bir süredir) kendini iyi hissetmiyordu.\nHow long had you been working there? — Orada ne zamandır çalışıyordun?'],
      ['Past Perfect Continuous ne zaman kullanılır?', '• Geçmişteki bir ana kadar süre\n• Geçmişteki bir durumun sebebi', 'They had been living in İzmir for years before they moved.\nThe ground was wet. It had been raining. — Yer ıslaktı; yağmur yağıyormuş.'],
      ['Future: will: yapı', 'Olumlu (+)  will + V1 (\'ll)\nOlumsuz (–)  won\'t (will not) + V1\nSoru (?)  Will + özne + V1?', 'I will help you. — Sana yardım edeceğim.\nIt won\'t take long. — Uzun sürmeyecek.\nWill you come? — Gelecek misin?'],
      ['Future: will ne zaman kullanılır?', '• Konuşma anında verilen karar\n• Tahmin, görüş (think, probably)\n• Söz, teklif, rica\n• Gerçekler (gelecekte)', 'The phone is ringing. I\'ll answer it. — Telefon çalıyor, ben bakarım.\nI think it will rain. — Bence yağmur yağacak.\nI will call you tonight. — Bu akşam seni arayacağım. Will you open the door?\nI will be 40 next year. — Seneye 40 yaşında olacağım.'],
      ['Future: be going to: yapı', 'Olumlu (+)  am / is / are going to + V1\nOlumsuz (–)  am not / isn\'t / aren\'t going to + V1\nSoru (?)  Am / Is / Are + özne + going to + V1?', 'I am going to buy a car. — Araba alacağım (niyetliyim).\nWe aren\'t going to travel. — Seyahat etmeyeceğiz.\nAre you going to study? — Ders çalışacak mısın?'],
      ['Future: be going to ne zaman kullanılır?', '• Önceden planlanmış niyet\n• Şu anki kanıta dayalı tahmin', 'We are going to move next month. — Gelecek ay taşınacağız.\nLook at those clouds! It is going to rain. — Şu bulutlara bak, yağmur yağacak.'],
      ['Future Continuous: yapı', 'Olumlu (+)  will be + V-ing\nOlumsuz (–)  won\'t be + V-ing\nSoru (?)  Will + özne + be + V-ing?', 'This time tomorrow I will be flying. — Yarın bu saatte uçuyor olacağım.\nI won\'t be working on Monday. — Pazartesi çalışıyor olmayacağım.\nWill you be using the car tonight? — Bu akşam arabayı kullanıyor olacak mısın?'],
      ['Future Continuous ne zaman kullanılır?', '• Gelecekte belli bir anda süren\n• Kibar soru (plan sormak)', 'At 9 pm I will be watching the match.\nWill you be joining us? — Bize katılacak mısınız?'],
      ['Future Perfect: yapı', 'Olumlu (+)  will have + V3\nOlumsuz (–)  won\'t have + V3\nSoru (?)  Will + özne + have + V3?', 'By 2027 I will have finished school. — 2027\'ye kadar okulu bitirmiş olacağım.\nThey won\'t have arrived by noon. — Öğlene kadar varmamış olacaklar.\nWill you have finished by 6? — 6\'ya kadar bitirmiş olacak mısın?'],
      ['Future Perfect ne zaman kullanılır?', '• Gelecekteki bir ana kadar tamamlanma', 'By the time you arrive, I will have cooked dinner. — Sen gelene kadar yemeği yapmış olacağım.'],
      ['Present Simple - Present Continuous farkı', 'I work in Ankara. — kalıcı (orada çalışırım)  ↔  I am working in Ankara this month. — geçici (bu ay)\nHe plays football. — alışkanlık/hobi  ↔  He is playing football. — şu an oynuyor\nWhat do you do? — Mesleğin ne?  ↔  What are you doing? — Şu an ne yapıyorsun?', ''],
      ['Past Simple - Present Perfect farkı', 'Zaman belli ve bitmiş: I lost my keys yesterday.  ↔  Zaman belli değil, etkisi şimdi: I have lost my keys.\nBitmiş dönem: She worked there for 5 years. (artık çalışmıyor)  ↔  Süren dönem: She has worked there for 5 years. (hâlâ çalışıyor)\nDid you see the film last night?  ↔  Have you seen the film? (hiç izledin mi?)\nyesterday, last, ago, in 2019, when...  ↔  ever, never, just, already, yet, for, since...', ''],
      ['will / be going to / Present Continuous / Present Simple (gelecek)', 'will: Anlık karar, tahmin, söz\nbe going to: Önceden düşünülmüş niyet; kanıtlı tahmin\nPresent Continuous: Saati, yeri ayarlanmış kesin plan\nPresent Simple: Tarife, resmî program', 'I\'m thirsty. — I\'ll get you some water.\nI\'m going to learn Spanish this year.\nI\'m flying to İstanbul on Friday. (bilet alındı)\nThe meeting starts at 10.'],
      ['Hata bul: When I will arrive, I\'ll call you.', 'Doğrusu: When I arrive, I\'ll call you.', 'Varınca seni arayacağım.'],
      ['Hata bul: If it will rain, we\'ll stay home.', 'Doğrusu: If it rains, we\'ll stay home.', 'Yağmur yağarsa evde kalırız.'],
      ['Hata bul: I\'ll wait until he will come.', 'Doğrusu: I\'ll wait until he comes.', 'O gelene kadar bekleyeceğim.'],
      ['Hata bul: I am live in Ankara.', 'Doğrusu: I live in Ankara.', 'Present Simple\'da am/is/are yok.'],
      ['Hata bul: She work here.', 'Doğrusu: She works here.', 'he/she/it → -s.'],
      ['Hata bul: I am knowing him.', 'Doğrusu: I know him.', 'Durum fiili -ing almaz.'],
      ['Hata bul: I have seen him yesterday.', 'Doğrusu: I saw him yesterday.', 'Belli geçmiş zaman → Past Simple.'],
      ['Hata bul: I live here since 2015.', 'Doğrusu: I have lived here since 2015.', 'since/for ile süren durum → Present Perfect.'],
      ['Hata bul: I am waiting for 2 hours.', 'Doğrusu: I have been waiting for 2 hours.', '"...dır bekliyorum" → Perfect Continuous.'],
      ['Hata bul: Did you went?', 'Doğrusu: Did you go?', 'did + V1.'],
      ['Hata bul: When I will finish, I\'ll call.', 'Doğrusu: When I finish, I\'ll call.', 'when\'den sonra will yok.'],
      ['Hata bul: He can to swim.', 'Doğrusu: He can swim.', 'Modal + V1 (to yok).'],
      ['Sürekli (-ing) almayan durum fiilleri', 'Düşünce / bilgi: know, believe, understand, remember, forget, think (=inanmak), mean, realise\nDuygu / istek: like, love, hate, want, need, prefer, wish\nSahiplik: have (=sahip olmak), own, belong, possess\nAlgı: see, hear, smell, taste, seem, look (=görünmek)\nDiğer: be, cost, contain, weigh, depend, agree', 'I am knowing him. ✗  →  I know him. ✓'],
    ]),
  ]),
];
